using System.Reflection;
using System.Reflection.Metadata;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>
/// Inspects the compiled assemblies, so a layer violation fails the build even when the
/// project references would allow it (e.g. System.IO or System.Net.Http used from business code).
/// Kept in its own project so the fast unit suite is unaffected.
/// </summary>
public class LayerDependencyTests
{
    // Framework namespaces that carry no technical detail (I/O, network, persistence, serialization...).
    private static readonly string[] AllowedFrameworkNamespaces =
    [
        "System",
        "System.Collections",
        "System.Collections.Generic",
        "System.Collections.Immutable",
        "System.Diagnostics.CodeAnalysis",
        "System.Linq",
        "System.Runtime.CompilerServices",
        "System.Threading",
        "System.Threading.Tasks",
    ];

    [Fact]
    public void Domain_depends_on_nothing_but_itself()
        => AssertOnlyUses(typeof(Money).Assembly, ["PaymentAuthorization.Domain"]);

    [Fact]
    public void Application_depends_only_on_domain_and_itself()
        => AssertOnlyUses(typeof(AuthorizePayment).Assembly, ["PaymentAuthorization.Domain", "PaymentAuthorization.Application"]);

    [Fact]
    public void Infrastructure_assembly_is_loadable_for_the_check() // guards against the layers being renamed silently
        => Assert.Equal("PaymentAuthorization.Infrastructure", typeof(HttpPaymentGateway).Namespace);

    private static void AssertOnlyUses(Assembly assembly, string[] ownNamespaces)
    {
        var violations = ReferencedTypes(assembly)
            .Where(t => !AllowedFrameworkNamespaces.Contains(t.Namespace) && !ownNamespaces.Contains(t.Namespace))
            .Select(t => $"{t.Namespace}.{t.Name}")
            .Distinct()
            .Order()
            .ToList();

        Assert.True(violations.Count == 0,
            $"{assembly.GetName().Name} must not depend on: {string.Join(", ", violations)}");
    }

    private static IEnumerable<(string Namespace, string Name)> ReferencedTypes(Assembly assembly)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new System.Reflection.PortableExecutable.PEReader(stream);
        var reader = pe.GetMetadataReader();
        var result = new List<(string, string)>();
        foreach (var handle in reader.TypeReferences)
        {
            var typeRef = reader.GetTypeReference(handle);
            if (typeRef.ResolutionScope.Kind == HandleKind.TypeReference) continue; // nested: the outer type is checked
            result.Add((reader.GetString(typeRef.Namespace), reader.GetString(typeRef.Name)));
        }
        return result;
    }
}
EOF
